import { test as base } from "./system-control-browser";
import "dotenv/config";
import { expect } from "@playwright/test";
import { Pool } from "pg";
import { randomUUID } from "node:crypto";
import { encode } from "next-auth/jwt";
import { requireTestDatabaseUrl } from "./foundation-db";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
export const test = base.extend<{ themeUser: string }, { themeDatabase: Pool }>(
  {
    themeDatabase: [
      async ({}, runWorker) => {
        try {
          await runWorker(pool);
        } finally {
          await pool.end();
        }
      },
      { scope: "worker" },
    ],
    themeUser: [
      async ({ context, themeDatabase }, runFixture) => {
        if (process.env.MAILLOOP_E2E_ISOLATED !== "1")
          throw new Error(
            "Run appearance tests with the disposable database runner.",
          );
        requireTestDatabaseUrl();
        const id = randomUUID();
        await themeDatabase.query(
          `INSERT INTO "User" (id,email,"googleId","gmailAuthorized",plan,"planOverride","planOverrideStartsAt","planOverrideReason","usageBackfillVersion","usageCutoverAt") VALUES ($1,$2,$1,false,'FREE','PAID',NOW(),'Theme fixture',1,NOW())`,
          [id, `${id}@example.test`],
        );
        const salt = "authjs.session-token";
        const token = await encode({
          secret: process.env.AUTH_SECRET!,
          salt,
          token: { userId: id, sub: id, email: `${id}@example.test` },
        });
        await context.addCookies([
          {
            name: salt,
            value: token,
            domain: "localhost",
            path: "/",
            httpOnly: true,
            sameSite: "Lax",
            expires: Date.now() / 1000 + 3600,
          },
        ]);
        try {
          await runFixture(id);
        } finally {
          await themeDatabase.query('DELETE FROM "User" WHERE id=$1', [id]);
        }
      },
      { auto: true },
    ],
  },
);

export async function setThemePlan(
  id: string,
  plan: "FREE" | "PAID",
  expiresAt: Date | null = null,
) {
  await pool.query(
    `UPDATE "User" SET "planOverride"=$2::"Plan","planOverrideStartsAt"=NOW(),"planOverrideExpiresAt"=$3 WHERE id=$1`,
    [id, plan, expiresAt?.toISOString() ?? null],
  );
}
export { expect };

export async function setThemeQuotaGating(enabled: boolean) {
  await pool.query(
    `UPDATE "SystemControl" SET "paidGatingEnabled"=$1 WHERE key='global'`,
    [enabled],
  );
}
